import type { TelemetryClient } from "./client.js";
import type { EventDimensionsMap } from "./generated/paperclip-telemetry.js";

type RawDimension<T extends string | undefined> = T | (string & {});

function asEventDimension<T extends string>(value: RawDimension<T>): T {
  return value as T;
}

export function trackInstallStarted(client: TelemetryClient): void {
  client.track("install.started", {});
}

export function trackInstallCompleted(
  client: TelemetryClient,
  dims: { adapterType: RawDimension<EventDimensionsMap["install.completed"]["adapter_type"]> },
): void {
  client.track("install.completed", {
    adapter_type: asEventDimension(dims.adapterType),
  });
}

export function trackCompanyImported(
  client: TelemetryClient,
  dims: {
    sourceType: RawDimension<EventDimensionsMap["company.imported"]["source_type"]>;
    sourceRef: string;
    isPrivate: boolean;
  },
): void {
  const ref = dims.isPrivate ? client.hashPrivateRef(dims.sourceRef) : dims.sourceRef;
  client.track("company.imported", {
    source_type: asEventDimension(dims.sourceType),
    source_ref: ref,
    source_ref_hashed: dims.isPrivate,
  });
}

export function trackProjectCreated(client: TelemetryClient): void {
  client.track("project.created", {});
}

export function trackRoutineCreated(client: TelemetryClient): void {
  client.track("routine.created", {});
}

export function trackRoutineRun(
  client: TelemetryClient,
  dims: {
    source: RawDimension<EventDimensionsMap["routine.run"]["source"]>;
    status: RawDimension<EventDimensionsMap["routine.run"]["status"]>;
  },
): void {
  client.track("routine.run", {
    source: asEventDimension(dims.source),
    status: asEventDimension(dims.status),
  });
}

export function trackGoalCreated(
  client: TelemetryClient,
  dims?: { goalLevel?: RawDimension<EventDimensionsMap["goal.created"]["goal_level"]> | null },
): void {
  client.track("goal.created", {
    goal_level: dims?.goalLevel ? asEventDimension(dims.goalLevel) : "other",
  });
}

export function trackAgentCreated(
  client: TelemetryClient,
  dims: {
    agentRole: RawDimension<EventDimensionsMap["agent.created"]["agent_role"]>;
    agentId: string;
  },
): void {
  client.track("agent.created", {
    agent_role: asEventDimension(dims.agentRole),
    agent_id: dims.agentId,
  });
}

export function trackSkillImported(
  client: TelemetryClient,
  dims: {
    sourceType: RawDimension<EventDimensionsMap["skill.imported"]["source_type"]>;
    skillRef?: string | null;
  },
): void {
  client.track("skill.imported", {
    source_type: asEventDimension(dims.sourceType),
    ...(dims.skillRef ? { skill_ref: dims.skillRef } : {}),
  });
}

export function trackAgentFirstHeartbeat(
  client: TelemetryClient,
  dims: {
    agentRole: RawDimension<EventDimensionsMap["agent.first_heartbeat"]["agent_role"]>;
    agentId: string;
  },
): void {
  client.track("agent.first_heartbeat", {
    agent_role: asEventDimension(dims.agentRole),
    agent_id: dims.agentId,
  });
}

export function trackAgentTaskCompleted(
  client: TelemetryClient,
  dims: {
    agentRole: RawDimension<EventDimensionsMap["agent.task_completed"]["agent_role"]>;
    agentId: string;
    adapterType: RawDimension<EventDimensionsMap["agent.task_completed"]["adapter_type"]>;
    model?: string;
    taskId?: string;
  },
): void {
  client.track("agent.task_completed", {
    agent_role: asEventDimension(dims.agentRole),
    agent_id: dims.agentId,
    adapter_type: asEventDimension(dims.adapterType),
    ...(dims.model ? { model: dims.model } : {}),
    ...(dims.taskId ? { task_id: client.hashPrivateRef(dims.taskId) } : {}),
  });
}

export function trackAgentTaskRun(
  client: TelemetryClient,
  dims: {
    agentId: string;
    state: RawDimension<EventDimensionsMap["agent.task_run"]["state"]>;
    adapterType?: RawDimension<EventDimensionsMap["agent.task_run"]["adapter_type"]>;
    agentRole?: RawDimension<EventDimensionsMap["agent.task_run"]["agent_role"]>;
    model?: string;
    durationSeconds?: number;
    inputTokens?: number;
    outputTokens?: number;
    cachedTokens?: number;
    taskId?: string;
  },
): void {
  client.track("agent.task_run", {
    agent_id: dims.agentId,
    state: asEventDimension(dims.state),
    ...(dims.adapterType ? { adapter_type: asEventDimension(dims.adapterType) } : {}),
    ...(dims.agentRole ? { agent_role: asEventDimension(dims.agentRole) } : {}),
    ...(dims.model ? { model: dims.model } : {}),
    ...(dims.durationSeconds === undefined ? {} : { duration_seconds: dims.durationSeconds }),
    ...(dims.inputTokens === undefined ? {} : { input_tokens: dims.inputTokens }),
    ...(dims.outputTokens === undefined ? {} : { output_tokens: dims.outputTokens }),
    ...(dims.cachedTokens === undefined ? {} : { cached_tokens: dims.cachedTokens }),
    ...(dims.taskId ? { task_id: client.hashPrivateRef(dims.taskId) } : {}),
  });
}

export function trackErrorHandlerCrash(
  client: TelemetryClient,
  dims: { errorCode: string },
): void {
  client.track("error.handler_crash", { error_code: dims.errorCode });
}

export function trackInteractionCreated(
  client: TelemetryClient,
  dims: {
    interactionKind: RawDimension<EventDimensionsMap["interaction.created"]["interaction_kind"]>;
    usedDeprecatedResolverPolicyAlias: boolean;
  },
): void {
  client.track("interaction.created", {
    interaction_kind: asEventDimension(dims.interactionKind),
    used_deprecated_resolver_policy_alias: dims.usedDeprecatedResolverPolicyAlias,
  });
}

export function trackInteractionResolved(
  client: TelemetryClient,
  dims: {
    interactionKind: RawDimension<EventDimensionsMap["interaction.resolved"]["interaction_kind"]>;
    status: RawDimension<EventDimensionsMap["interaction.resolved"]["status"]>;
    resolvedByKind: RawDimension<EventDimensionsMap["interaction.resolved"]["resolved_by_kind"]>;
    resolutionReason?: RawDimension<EventDimensionsMap["interaction.resolved"]["resolution_reason"]> | null;
    createdByKind?: RawDimension<EventDimensionsMap["interaction.resolved"]["created_by_kind"]> | null;
    creatorAgentRole?: RawDimension<EventDimensionsMap["interaction.resolved"]["creator_agent_role"]> | null;
    continuationPolicy?: RawDimension<EventDimensionsMap["interaction.resolved"]["continuation_policy"]> | null;
    targetType?: RawDimension<EventDimensionsMap["interaction.resolved"]["target_type"]> | null;
    optionCount?: number;
    selectedOptionCount?: number;
    questionCount?: number;
    answeredQuestionCount?: number;
    createdTaskCount?: number;
    skippedTaskCount?: number;
    legacyInheritedRestriction: boolean;
  },
): void {
  client.track("interaction.resolved", {
    interaction_kind: asEventDimension(dims.interactionKind),
    status: asEventDimension(dims.status),
    resolved_by_kind: asEventDimension(dims.resolvedByKind),
    ...(dims.resolutionReason ? { resolution_reason: asEventDimension(dims.resolutionReason) } : {}),
    ...(dims.createdByKind ? { created_by_kind: asEventDimension(dims.createdByKind) } : {}),
    ...(dims.creatorAgentRole ? { creator_agent_role: asEventDimension(dims.creatorAgentRole) } : {}),
    ...(dims.continuationPolicy ? { continuation_policy: asEventDimension(dims.continuationPolicy) } : {}),
    ...(dims.targetType ? { target_type: asEventDimension(dims.targetType) } : {}),
    ...(dims.optionCount === undefined ? {} : { option_count: dims.optionCount }),
    ...(dims.selectedOptionCount === undefined ? {} : { selected_option_count: dims.selectedOptionCount }),
    ...(dims.questionCount === undefined ? {} : { question_count: dims.questionCount }),
    ...(dims.answeredQuestionCount === undefined ? {} : { answered_question_count: dims.answeredQuestionCount }),
    ...(dims.createdTaskCount === undefined ? {} : { created_task_count: dims.createdTaskCount }),
    ...(dims.skippedTaskCount === undefined ? {} : { skipped_task_count: dims.skippedTaskCount }),
    legacy_inherited_restriction: dims.legacyInheritedRestriction,
  });
}

import { createHash } from "node:crypto";
import { describe, expect, it, vi } from "vitest";
import {
  trackAgentCreated,
  trackAgentFirstHeartbeat,
  trackAgentTaskCompleted,
  trackAgentTaskRun,
  trackInteractionCreated,
  trackInteractionResolved,
  trackInstallCompleted,
} from "@paperclipai/shared/telemetry";
import type { EventDimensionsMap, TelemetryClient } from "@paperclipai/shared/telemetry";

function createClient(): TelemetryClient {
  return {
    track: vi.fn(),
    hashPrivateRef: vi.fn((value: string) => createHash("sha256").update(value).digest("hex").slice(0, 16)),
  } as unknown as TelemetryClient;
}

function runtimeValue<T>(value: string): T {
  return value as T;
}

describe("shared telemetry agent events", () => {
  it("includes agent_id for agent.created", () => {
    const client = createClient();

    trackAgentCreated(client, {
      agentRole: "engineer",
      agentId: "11111111-1111-4111-8111-111111111111",
    });

    expect(client.track).toHaveBeenCalledWith("agent.created", {
      agent_role: "engineer",
      agent_id: "11111111-1111-4111-8111-111111111111",
    });
  });

  it("passes an unrecognized agent role through for backend normalization", () => {
    const client = createClient();

    trackAgentCreated(client, {
      agentRole: runtimeValue<EventDimensionsMap["agent.created"]["agent_role"]>("coder"),
      agentId: "44444444-4444-4444-8444-444444444444",
    });

    expect(client.track).toHaveBeenCalledWith("agent.created", {
      agent_role: "coder",
      agent_id: "44444444-4444-4444-8444-444444444444",
    });
  });

  it("includes agent_id for agent.first_heartbeat", () => {
    const client = createClient();

    trackAgentFirstHeartbeat(client, {
      agentRole: "engineer",
      agentId: "22222222-2222-4222-8222-222222222222",
    });

    expect(client.track).toHaveBeenCalledWith("agent.first_heartbeat", {
      agent_role: "engineer",
      agent_id: "22222222-2222-4222-8222-222222222222",
    });
  });

  it("includes agent_id for agent.task_completed", () => {
    const client = createClient();

    trackAgentTaskCompleted(client, {
      agentRole: "qa",
      agentId: "33333333-3333-4333-8333-333333333333",
      adapterType: "codex_local",
    });

    expect(client.track).toHaveBeenCalledWith("agent.task_completed", {
      agent_role: "qa",
      agent_id: "33333333-3333-4333-8333-333333333333",
      adapter_type: "codex_local",
    });
  });

  it("hashes the task id for agent.task_completed and never sends the raw value", () => {
    const client = createClient();
    const rawTaskId = "11111111-1111-4111-8111-111111111111";

    trackAgentTaskCompleted(client, {
      agentRole: "qa",
      agentId: "33333333-3333-4333-8333-333333333333",
      adapterType: "codex_local",
      taskId: rawTaskId,
    });

    expect(client.hashPrivateRef).toHaveBeenCalledWith(rawTaskId);
    const sentDimensions = vi.mocked(client.track).mock.calls[0]?.[1] as Record<string, unknown>;
    expect(sentDimensions.task_id).toMatch(/^[0-9a-f]{16}$/);
    expect(sentDimensions.task_id).not.toBe(rawTaskId);
    expect(JSON.stringify(sentDimensions)).not.toContain(rawTaskId);
  });

  it("omits task_id for agent.task_completed when the caller gives no task id", () => {
    const client = createClient();

    trackAgentTaskCompleted(client, {
      agentRole: "qa",
      agentId: "33333333-3333-4333-8333-333333333333",
      adapterType: "codex_local",
    });

    expect(client.hashPrivateRef).not.toHaveBeenCalled();
    expect(client.track).toHaveBeenCalledWith("agent.task_completed", {
      agent_role: "qa",
      agent_id: "33333333-3333-4333-8333-333333333333",
      adapter_type: "codex_local",
    });
  });

  it("sends all ten dimensions for agent.task_run when present", () => {
    const client = createClient();
    const rawTaskId = "22222222-2222-4222-8222-222222222222";

    trackAgentTaskRun(client, {
      agentId: "44444444-4444-4444-8444-444444444444",
      state: "succeeded",
      adapterType: "claude_local",
      agentRole: "engineer",
      model: "claude-sonnet-5",
      durationSeconds: 12.5,
      inputTokens: 100,
      outputTokens: 200,
      cachedTokens: 50,
      taskId: rawTaskId,
    });

    expect(client.hashPrivateRef).toHaveBeenCalledWith(rawTaskId);
    const sentDimensions = vi.mocked(client.track).mock.calls[0]?.[1] as Record<string, unknown>;
    expect(sentDimensions).toMatchObject({
      agent_id: "44444444-4444-4444-8444-444444444444",
      state: "succeeded",
      adapter_type: "claude_local",
      agent_role: "engineer",
      model: "claude-sonnet-5",
      duration_seconds: 12.5,
      input_tokens: 100,
      output_tokens: 200,
      cached_tokens: 50,
    });
    expect(sentDimensions.task_id).toMatch(/^[0-9a-f]{16}$/);
  });

  it("omits every absent optional dimension for agent.task_run", () => {
    const client = createClient();

    trackAgentTaskRun(client, {
      agentId: "55555555-5555-4555-8555-555555555555",
      state: "failed",
    });

    expect(client.hashPrivateRef).not.toHaveBeenCalled();
    expect(client.track).toHaveBeenCalledWith("agent.task_run", {
      agent_id: "55555555-5555-4555-8555-555555555555",
      state: "failed",
    });
  });

  it("keeps non-agent event dimensions unchanged", () => {
    const client = createClient();

    trackInstallCompleted(client, { adapterType: "codex_local" });

    expect(client.track).toHaveBeenCalledWith("install.completed", {
      adapter_type: "codex_local",
    });
    expect(client.track).not.toHaveBeenCalledWith(
      "install.completed",
      expect.objectContaining({ agent_id: expect.any(String) }),
    );
  });

  it("passes interaction.resolved enum dimensions through for backend normalization", () => {
    const client = createClient();

    trackInteractionResolved(client, {
      interactionKind: runtimeValue<EventDimensionsMap["interaction.resolved"]["interaction_kind"]>(
        "single_confirmation",
      ),
      status: "accepted",
      resolvedByKind: runtimeValue<EventDimensionsMap["interaction.resolved"]["resolved_by_kind"]>("operator"),
      resolutionReason: "accepted",
      createdByKind: "agent",
      creatorAgentRole: runtimeValue<EventDimensionsMap["interaction.resolved"]["creator_agent_role"]>("coder"),
      continuationPolicy: runtimeValue<EventDimensionsMap["interaction.resolved"]["continuation_policy"]>(
        "wake_everyone",
      ),
      targetType: "issue_document",
      optionCount: 2,
      selectedOptionCount: 1,
      skippedTaskCount: 3,
      legacyInheritedRestriction: true,
    });

    expect(client.track).toHaveBeenCalledWith("interaction.resolved", {
      interaction_kind: "single_confirmation",
      status: "accepted",
      resolved_by_kind: "operator",
      resolution_reason: "accepted",
      created_by_kind: "agent",
      creator_agent_role: "coder",
      continuation_policy: "wake_everyone",
      target_type: "issue_document",
      option_count: 2,
      selected_option_count: 1,
      skipped_task_count: 3,
      legacy_inherited_restriction: true,
    });
  });

  it("emits only enum and boolean dimensions for interaction creation compatibility", () => {
    const client = createClient();

    trackInteractionCreated(client, {
      interactionKind: "request_confirmation",
      usedDeprecatedResolverPolicyAlias: true,
    });

    expect(client.track).toHaveBeenCalledWith("interaction.created", {
      interaction_kind: "request_confirmation",
      used_deprecated_resolver_policy_alias: true,
    });
  });
});

package io.kestra.cli.commands.flows;

import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

import io.kestra.cli.AbstractApiCommand;
import io.kestra.cli.services.TenantIdSelectorService;

import io.micronaut.http.HttpRequest;
import io.micronaut.http.HttpResponse;
import io.micronaut.http.MediaType;
import io.micronaut.http.MutableHttpRequest;
import io.micronaut.http.client.exceptions.HttpClientResponseException;
import io.micronaut.http.client.netty.DefaultHttpClient;
import jakarta.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import picocli.CommandLine;

@CommandLine.Command(
    name = "export",
    description = "Export flows to a ZIP file",
    mixinStandardHelpOptions = true
)
@Slf4j
public class FlowExportCommand extends AbstractApiCommand {
    private static final String DEFAULT_FILE_NAME = "flows.zip";

    @Inject
    private TenantIdSelectorService tenantService;

    @CommandLine.Option(names = { "--namespace" }, description = "The namespace of flows to export", required = true)
    public String namespace;

    @CommandLine.Parameters(index = "0", description = "The directory to export the ZIP file to")
    public Path directory;

    @Override
    public Integer call() throws Exception {
        super.call();

        try (DefaultHttpClient client = client()) {
            MutableHttpRequest<Object> request = HttpRequest
                // The endpoint only binds filters in the bracket format, so the flat `namespace=` param was never
                // read and `--namespace` exported the whole tenant (kestra-io/kestra-ee#10394); PREFIX keeps the
                // documented meaning of the option, the namespace and its children.
                .GET(apiUri("/flows/export/by-query", tenantService.getTenantId(tenantId))
                    + (namespace != null ? "?filters[namespace][PREFIX]=" + URLEncoder.encode(namespace, StandardCharsets.UTF_8) : ""))
                .accept(MediaType.APPLICATION_OCTET_STREAM);

            HttpResponse<byte[]> response = client.toBlocking().exchange(this.requestOptions(request), byte[].class);
            Path zipFile = Path.of(directory.toString(), DEFAULT_FILE_NAME);
            zipFile.toFile().createNewFile();
            Files.write(zipFile, response.body());

            stdOut("Exporting flow(s) for namespace '" + namespace + "' successfully done !");
        } catch (HttpClientResponseException e) {
            stdErr("\t@|fg(red) Unable to parse flows due to the following error:|@");
            stdErr(
                "\t- @|bold,yellow {0}|@",
                e.getMessage()
            );
            return 1;
        }

        return 0;
    }

}

package io.kestra.cli.services;

import java.io.IOException;
import java.nio.charset.Charset;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.CopyOnWriteArrayList;

import io.kestra.core.exceptions.FlowProcessingException;
import io.kestra.core.models.flows.FlowInterface;
import io.kestra.core.models.flows.FlowWithPath;
import io.kestra.core.models.flows.FlowWithSource;
import io.kestra.core.models.flows.GenericFlow;
import io.kestra.core.models.validations.ModelValidator;
import io.kestra.core.queues.BroadcastQueueInterface;
import io.kestra.core.repositories.FlowRepositoryInterface;
import io.kestra.core.services.FlowParsingService;
import io.kestra.core.services.FlowService;

import io.micronaut.context.annotation.Requires;
import io.micronaut.scheduling.io.watch.FileWatchConfiguration;
import jakarta.annotation.Nullable;
import jakarta.annotation.PreDestroy;
import jakarta.inject.Inject;
import jakarta.inject.Singleton;
import jakarta.validation.ConstraintViolationException;
import lombok.extern.slf4j.Slf4j;

import static io.kestra.core.utils.Rethrow.throwConsumer;

@Singleton
@Slf4j
@Requires(property = "micronaut.io.watch.enabled", value = "true")
public class FileChangedEventListener {
    @Nullable
    private final FileWatchConfiguration fileWatchConfiguration;
    private final WatchService watchService;

    @Inject
    private FlowRepositoryInterface flowRepositoryInterface;

    @Inject
    private FlowService flowService;

    @Inject
    private FlowParsingService flowParsingService;

    @Inject
    private ModelValidator modelValidator;

    @Inject
    private BroadcastQueueInterface<FlowInterface> flowQueue;

    private FlowFilesManager flowFilesManager;
    private Runnable cancellation;

    private final List<FlowWithPath> flows = new CopyOnWriteArrayList<>();

    @Inject
    public FileChangedEventListener(@Nullable FileWatchConfiguration fileWatchConfiguration, WatchService watchService) {
        this.fileWatchConfiguration = fileWatchConfiguration;
        this.watchService = watchService;
    }

    public void startListeningFromConfig() throws IOException, InterruptedException {
        if (fileWatchConfiguration != null && fileWatchConfiguration.isEnabled()) {
            this.flowFilesManager = new LocalFlowFileWatcher(flowRepositoryInterface, flowService);
            List<Path> paths = fileWatchConfiguration.getPaths();
            this.setup(paths);

            // Init existing flows not already in files
            flowRepositoryInterface.findAllWithSourceForAllTenants().forEach(flow ->
            {
                flowToFile(flow, this.buildPath(flow));
                flows.add(FlowWithPath.of(flow, this.buildPath(flow).toString()));
            });

            // Listen for new/updated/deleted flows
            flowQueue.addListener(current ->
            {
                // If deleted
                if (current.isDeleted()) {
                    this.flows.stream().filter(flowWithPath -> flowWithPath.uidWithoutRevision().equals(current.uidWithoutRevision())).findFirst()
                        .ifPresent(flowWithPath ->
                        {
                            deleteFile(Paths.get(flowWithPath.getPath()));
                        });
                    this.flows.removeIf(flowWithPath -> flowWithPath.uidWithoutRevision().equals(current.uidWithoutRevision()));
                } else {
                    // if updated/created
                    Optional<FlowWithPath> flowWithPath = this.flows.stream().filter(fwp -> fwp.uidWithoutRevision().equals(current.uidWithoutRevision())).findFirst();
                    if (flowWithPath.isPresent()) {
                        flowToFile(current, Paths.get(flowWithPath.get().getPath()));
                    } else {
                        flows.add(FlowWithPath.of(current, this.buildPath(current).toString()));
                        flowToFile(current, null);
                    }
                }
            });

            this.startListening(paths);
        } else {
            log.info("File watching is disabled.");
        }
    }

    @PreDestroy
    void close() {
        cancellation.run();
    }

    public void startListening(List<Path> paths) throws IOException, InterruptedException {
        for (Path path : paths) {
            path.register(watchService, StandardWatchEventKinds.ENTRY_CREATE, StandardWatchEventKinds.ENTRY_DELETE, StandardWatchEventKinds.ENTRY_MODIFY);
        }

        WatchKey key;
        while ((key = watchService.take()) != null) {
            for (WatchEvent<?> watchEvent : key.pollEvents()) {
                try {
                    WatchEvent.Kind<?> kind = watchEvent.kind();
                    Path entry = (Path) watchEvent.context();

                    if (entry.toString().endsWith(".yml") || entry.toString().endsWith(".yaml")) {

                        if (kind == StandardWatchEventKinds.ENTRY_CREATE || kind == StandardWatchEventKinds.ENTRY_MODIFY) {

                            Path filePath = ((Path) key.watchable()).resolve(entry);
                            if (Files.isDirectory(filePath)) {
                                loadFlowsFromFolder(filePath);
                            } else {

                                try {
                                    String content = Files.readString(filePath, Charset.defaultCharset());

                                    Optional<FlowWithSource> flow = parseFlow(content, entry);
                                    if (flow.isPresent()) {
                                        if (kind == StandardWatchEventKinds.ENTRY_MODIFY) {
                                            // Check if we already have a file with the given path
                                            if (flows.stream().anyMatch(flowWithPath -> flowWithPath.getPath().equals(filePath.toString()))) {
                                                Optional<FlowWithPath> previous = flows.stream().filter(flowWithPath -> flowWithPath.getPath().equals(filePath.toString())).findFirst();
                                                // Check if Flow from file has id/namespace updated
                                                if (previous.isPresent() && !previous.get().uidWithoutRevision().equals(flow.get().uidWithoutRevision())) {
                                                    flows.removeIf(flowWithPath -> flowWithPath.getPath().equals(filePath.toString()));
                                                    flowFilesManager.deleteFlow(previous.get().getTenantId(), previous.get().getNamespace(), previous.get().getId());
                                                    flows.add(FlowWithPath.of(flow.get(), filePath.toString()));
                                                }
                                            } else {
                                                flows.add(FlowWithPath.of(flow.get(), filePath.toString()));
                                            }
                                        } else {
                                            flows.add(FlowWithPath.of(flow.get(), filePath.toString()));
                                        }

                                        flowFilesManager.createOrUpdateFlow(GenericFlow.fromYaml(getTenantIdFromPath(filePath), content));
                                        log.info("Flow {} from file {} has been created or modified", flow.get().getId(), entry);
                                    }

                                } catch (NoSuchFileException e) {
                                    log.warn("File not found: {}, deleting it", entry, e);
                                    // the file might have been deleted while reading so if not found we try to delete the flow
                                    flows.stream()
                                        .filter(flow -> flow.getPath().equals(filePath.toString()))
                                        .findFirst()
                                        .ifPresent(throwConsumer(flowWithPath ->
                                        {
                                            flowFilesManager.deleteFlow(flowWithPath.getTenantId(), flowWithPath.getNamespace(), flowWithPath.getId());
                                            this.flows.removeIf(fwp -> fwp.uidWithoutRevision().equals(flowWithPath.uidWithoutRevision()));
                                        }));
                                } catch (IOException e) {
                                    log.error("Error reading file: {}", entry, e);
                                }
                            }
                        } else {
                            Path filePath = ((Path) key.watchable()).resolve(entry);
                            flows.stream()
                                .filter(flow -> flow.getPath().equals(filePath.toString()))
                                .findFirst()
                                .ifPresent(throwConsumer(flowWithPath ->
                                {
                                    flowFilesManager.deleteFlow(flowWithPath.getTenantId(), flowWithPath.getNamespace(), flowWithPath.getId());
                                    this.flows.removeIf(fwp -> fwp.uidWithoutRevision().equals(flowWithPath.uidWithoutRevision()));
                                }));
                        }
                    }
                } catch (Exception e) {
                    log.error("Unexpected error while watching flows", e);
                }
            }
            key.reset();
        }
    }

    private void setup(List<Path> folders) {
        for (Path folder : folders) {
            this.loadFlowsFromFolder(folder);
        }
    }

    private void loadFlowsFromFolder(Path folder) {
        try {
            Files.walkFileTree(folder, new SimpleFileVisitor<Path>() {
                @Override
                public FileVisitResult preVisitDirectory(Path dir, BasicFileAttributes attrs) throws IOException {
                    dir.register(watchService, StandardWatchEventKinds.ENTRY_CREATE, StandardWatchEventKinds.ENTRY_DELETE, StandardWatchEventKinds.ENTRY_MODIFY);
                    if (!dir.equals(folder)) {
                        loadFlowsFromFolder(dir);
                    }
                    return FileVisitResult.CONTINUE;
                }

                @Override
                public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                    if (file.toString().endsWith(".yml") || file.toString().endsWith(".yaml")) {
                        String content = Files.readString(file, Charset.defaultCharset());
                        Optional<FlowWithSource> flow = parseFlow(content, file);

                        if (flow.isPresent() && flows.stream().noneMatch(flowWithPath -> flowWithPath.uidWithoutRevision().equals(flow.get().uidWithoutRevision()))) {
                            flows.add(FlowWithPath.of(flow.get(), file.toString()));
                            try {
                                flowFilesManager.createOrUpdateFlow(GenericFlow.fromYaml(getTenantIdFromPath(file), content));
                            } catch (Exception e) {
                                log.error("Unexpected error while watching flows", e);
                            }
                        }
                    }
                    return FileVisitResult.CONTINUE;
                }
            });
            log.info("Loaded files from the folder {}", folder);
        } catch (IOException e) {
            log.error(e.getMessage());
        }
    }

    private void flowToFile(FlowInterface flow, Path path) {
        Path defaultPath = path != null ? path : this.buildPath(flow);

        String source = flow.sourceOrGenerateIfNull();
        if (source == null || source.isBlank()) {
            log.warn("Flow {} has no source, skipping file write to {}", flow.getId(), defaultPath);
            return;
        }

        try {
            Files.writeString(defaultPath, source);
            log.info("Flow {} has been written to file {}", flow.getId(), defaultPath);
        } catch (IOException e) {
            log.error("Error writing file: {}", defaultPath, e);
        }
    }

    private Optional<FlowWithSource> parseFlow(String content, Path entry) {
        try {
            FlowWithSource flow = flowParsingService.parse(getTenantIdFromPath(entry), content, false);
            modelValidator.validate(flow);
            return Optional.of(flow);
        } catch (ConstraintViolationException | FlowProcessingException e) {
            log.warn("Error while parsing flow: {}", entry, e);
        }
        return Optional.empty();
    }

    private void deleteFile(Path file) {
        try {
            if (Files.deleteIfExists(file)) {
                log.info("File {} has been deleted successfully.", file);
            } else {
                log.warn("File {} does not exist.", file);
            }
        } catch (IOException e) {
            log.error("Error deleting file: {}", file, e);
        }
    }

    private Path buildPath(FlowInterface flow) {
        return fileWatchConfiguration.getPaths().getFirst().resolve(flow.uidWithoutRevision() + ".yml");
    }

    private String getTenantIdFromPath(Path path) {
        // FIXME there is probably a bug here when a tenant has '_' in its name,
        //  a valid tenant name is defined with following regex: "^[a-z0-9][a-z0-9_-]*"
        return path.getFileName().toString().split("_")[0];
    }
}

let currentSort = { key: 'timestamp', direction: 'desc' }; // Set default sort to 'timestamp' descending
let allLogs = []; // Holds all fetched logs
let filteredLogs = []; // Holds logs after filtering
let rootLogs = []; // Holds the root logs after building the tree

// Fetch unique values for function names and log types to populate filter dropdowns
async function populateFilters() {
    try {
        const response = await fetch(apiLogsUrl);
        if (!response.ok) {
            throw new Error('Failed to fetch logs for filters');
        }
        let logs = await response.json();

        // **Sort logs by timestamp descending (most recent first)**
        logs.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));

        allLogs = logs;
        filteredLogs = logs;

        const functionFilter = document.getElementById('functionFilter');
        const logTypeFilter = document.getElementById('logTypeFilter');

        const uniqueFunctions = [...new Set(logs.map(log => log.function_name))].sort();
        uniqueFunctions.forEach(func => {
            const option = document.createElement('option');
            option.value = func;
            option.textContent = func;
            functionFilter.appendChild(option);
        });

        const uniqueLogTypes = [...new Set(logs.map(log => log.log_type))].sort();
        uniqueLogTypes.forEach(type => {
            const option = document.createElement('option');
            option.value = type;
            option.textContent = capitalizeFirstLetter(type);
            logTypeFilter.appendChild(option);
        });

        // Build the tree structure
        rootLogs = buildLogTree(filteredLogs);

        renderLogs();
    } catch (error) {
        console.error('Error populating filters:', error);
        alert('Failed to load logs for filters. Please try again later.');
    }
}

// Build log tree based on parent_log_id
function buildLogTree(logs) {
    const logsById = {};
    const rootLogs = [];

    // Initialize logsById mapping and add children array to each log
    logs.forEach(log => {
        log.children = [];
        logsById[log.id] = log;
    });

    // Build the tree
    logs.forEach(log => {
        if (log.parent_log_id !== null) {
            const parentLog = logsById[log.parent_log_id];
            if (parentLog) {
                parentLog.children.push(log);
            } else {
                // Parent log not found, treat as root
                rootLogs.push(log);
            }
        } else {
            rootLogs.push(log);
        }
    });

    return rootLogs;
}

// Render logs in table and grid formats
function renderLogs() {
    renderTable();
    renderGrid();
}

// Render Logs Table (Desktop View)
function renderTable() {
    const tableBody = document.querySelector('#logTable tbody');
    tableBody.innerHTML = '';

    rootLogs.forEach(log => {
        renderLogRow(tableBody, log, 0);
    });
}

// Recursive function to render each log row and its children
function renderLogRow(tableBody, log, depth, parentRowId) {
    const row = document.createElement('tr');
    const rowId = 'log-' + log.id;
    row.id = rowId;

    // If it's a child row, add a class to indicate it's a child
    if (parentRowId) {
        row.classList.add('child-of-log-' + parentRowId);
        row.style.display = 'none'; // Hide child rows by default
    }

    // Check if log has children
    const hasChildren = log.children && log.children.length > 0;

    // Create expand/collapse icon
    let toggleIcon = '';
    if (hasChildren) {
        toggleIcon = `<span class="toggle-icon" data-log-id="${log.id}" style="cursor:pointer;">[+]</span> `;
    }

    row.innerHTML = `
        <td><a href="${dashboardRoute}/log/${log.id}" class="function-link">${log.id}</a></td>
        <td><a href="${dashboardRoute}/function/${encodeURIComponent(log.function_name)}" class="function-link">${log.function_name}</a></td>
        <td style="padding-left:${depth * 20}px">${toggleIcon}${log.message}</td>
        <td>${new Date(log.timestamp).toLocaleString()}</td>
        <td>${capitalizeFirstLetter(log.log_type)}</td>
        <td>${log.time_spent ? log.time_spent.toFixed(3) : 'N/A'}</td>
        <td>${log.parent_log_id !== null ? log.parent_log_id : 'N/A'}</td>
        <td>${log.triggered_by_log_id !== null ? log.triggered_by_log_id : 'N/A'}</td>
    `;
    tableBody.appendChild(row);

    // Add event listener for toggle
    if (hasChildren) {
        row.querySelector('.toggle-icon').addEventListener('click', function() {
            toggleChildRows(log.id);
            // Update the icon
            const icon = this;
            if (icon.textContent === '[+]') {
                icon.textContent = '[-]';
            } else {
                icon.textContent = '[+]';
            }
        });
    }

    // Recursively render children
    if (hasChildren) {
        log.children.forEach(childLog => {
            renderLogRow(tableBody, childLog, depth + 1, log.id);
        });
    }
}

// Function to toggle child rows
function toggleChildRows(parentLogId) {
    const childRows = document.querySelectorAll('.child-of-log-' + parentLogId);

    childRows.forEach(row => {
        if (row.style.display === 'none') {
            row.style.display = '';
        } else {
            row.style.display = 'none';
            // Recursively hide any child rows
            const childLogId = row.id.replace('log-', '');
            toggleChildRows(childLogId);
            // Reset the toggle icon of child rows to '[+]'
            const toggleIcon = row.querySelector('.toggle-icon');
            if (toggleIcon) {
                toggleIcon.textContent = '[+]';
            }
        }
    });
}

// Render Logs Grid (Mobile View)
function renderGrid() {
    const logGrid = document.getElementById('logGrid');
    logGrid.innerHTML = '';

    rootLogs.forEach(log => {
        renderLogCard(logGrid, log, 0);
    });
}

// Recursive function to render log cards and their children
function renderLogCard(container, log, depth) {
    const card = document.createElement('div');
    card.className = 'log-card';
    card.style.marginLeft = (depth * 20) + 'px';

    card.innerHTML = `
        <h5>ID: <a href="${dashboardRoute}/log/${log.id}" class="function-link">${log.id}</a></h5>
        <div class="log-meta">Function: <a href="${dashboardRoute}/function/${encodeURIComponent(log.function_name)}">${log.function_name}</a> | ${new Date(log.timestamp).toLocaleString()}</div>
        <div class="log-details"><strong>Message:</strong> ${log.message}</div>
        <div class="log-details"><strong>Log Type:</strong> ${capitalizeFirstLetter(log.log_type)}</div>
        <div class="log-details"><strong>Time Spent:</strong> ${log.time_spent ? log.time_spent.toFixed(3) : 'N/A'} seconds</div>
        <div class="log-details"><strong>Parent Log ID:</strong> ${log.parent_log_id !== null ? log.parent_log_id : 'N/A'}</div>
        <div class="log-details"><strong>Triggered By Log ID:</strong> ${log.triggered_by_log_id !== null ? log.triggered_by_log_id : 'N/A'}</div>
    `;
    container.appendChild(card);

    // Recursively render children
    if (log.children && log.children.length > 0) {
        log.children.forEach(childLog => {
            renderLogCard(container, childLog, depth + 1);
        });
    }
}

// Capitalize the first letter of a string
function capitalizeFirstLetter(string) {
    return string.charAt(0).toUpperCase() + string.slice(1);
}

// Sort logs based on a key
function sortLogs(key) {
    if (currentSort.key === key) {
        currentSort.direction = currentSort.direction === 'asc' ? 'desc' : 'asc';
    } else {
        currentSort.key = key;
        currentSort.direction = 'asc';
    }

    // Sort root logs
    rootLogs.sort((a, b) => {
        let valA = a[key];
        let valB = b[key];

        // Handle null or undefined values
        if (valA === null || valA === undefined) valA = '';
        if (valB === null || valB === undefined) valB = '';

        // If sorting by timestamp, convert to Date
        if (key === 'timestamp') {
            valA = new Date(valA);
            valB = new Date(valB);
        }

        // If sorting by time_spent or IDs, ensure numerical comparison
        if (key === 'time_spent' || key === 'id' || key === 'parent_log_id' || key === 'triggered_by_log_id') {
            valA = Number(valA);
            valB = Number(valB);
        }

        if (valA > valB) return currentSort.direction === 'asc' ? 1 : -1;
        if (valA < valB) return currentSort.direction === 'asc' ? -1 : 1;
        return 0;
    });

    renderLogs();
}

// Apply Filters
function applyFilters() {
    const functionFilter = document.getElementById('functionFilter').value.toLowerCase();
    const logTypeFilter = document.getElementById('logTypeFilter').value.toLowerCase();
    const startDate = document.getElementById('startDate').value;
    const endDate = document.getElementById('endDate').value;

    // First, filter the logs
    filteredLogs = allLogs.filter(log => {
        let matchesFunction = true;
        let matchesLogType = true;
        let matchesStartDate = true;
        let matchesEndDate = true;

        if (functionFilter) {
            matchesFunction = log.function_name.toLowerCase().includes(functionFilter);
        }

        if (logTypeFilter) {
            matchesLogType = log.log_type.toLowerCase() === logTypeFilter;
        }

        if (startDate) {
            matchesStartDate = new Date(log.timestamp) >= new Date(startDate);
        }

        if (endDate) {
            // Add one day to endDate to include the entire end day
            const endDateObj = new Date(endDate);
            endDateObj.setDate(endDateObj.getDate() + 1);
            matchesEndDate = new Date(log.timestamp) < endDateObj;
        }

        return matchesFunction && matchesLogType && matchesStartDate && matchesEndDate;
    });

    // Rebuild the tree
    rootLogs = buildLogTree(filteredLogs);

    renderLogs();
}

// Reset Filters
function resetFilters() {
    document.getElementById('functionFilter').value = '';
    document.getElementById('logTypeFilter').value = '';
    document.getElementById('startDate').value = '';
    document.getElementById('endDate').value = '';
    filteredLogs = allLogs;

    // Rebuild the tree
    rootLogs = buildLogTree(filteredLogs);

    renderLogs();
}

