}

function renderGraph(logs) {
    // Process logs and build graph data
    const elements = logs.map(log => ({
        data: { id: log.id, label: log.function_name }
    }));

    // Add edges for relationships
    logs.forEach(log => {
        if (log.parent_log_id) {
            elements.push({
                data: {
                    id: `parent-${log.id}`,
                    source: log.parent_log_id,
                    target: log.id,
                    label: 'Parent'
                }
            });
        }
        if (log.triggered_by_log_id) {
            elements.push({
                data: {
                    id: `trigger-${log.id}`,
                    source: log.triggered_by_log_id,
                    target: log.id,
                    label: 'Triggered By'
                }
            });
        }
    });

    // Initialize Cytoscape graph
    var cy = cytoscape({
        container: document.getElementById('graph'),
        elements: elements,
        style: [
            {
                selector: 'node',
                style: {
                    'label': 'data(label)',
                    'background-color': '#666',
                    'text-valign': 'center',
                    'text-halign': 'center',
                    'color': '#fff',
                    'text-outline-width': 2,
                    'text-outline-color': '#666'
                }
            },
            {
                selector: 'edge',
                style: {
                    'width': 2,
                    'line-color': '#ccc',
                    'target-arrow-color': '#ccc',
                    'target-arrow-shape': 'triangle',
                    'curve-style': 'bezier'
                }
            }
        ],
        layout: {
            name: 'breadthfirst',
            directed: true,
            padding: 10
        }
    });

    // Add event listeners if needed
}

// Package broker provides Redis-based event pub/sub for distributed mode.
// This package is designed to be a lightweight dependency that can be imported
// without creating import cycles.
package broker

import (
	"context"
	"fmt"
	"github.com/j3ssie/osmedeus/v5/internal/json"
	"sync"
	"time"

	"github.com/google/uuid"
	"github.com/j3ssie/osmedeus/v5/internal/config"
	"github.com/j3ssie/osmedeus/v5/internal/core"
	"github.com/redis/rueidis"
)

// Redis key prefixes for events
const (
	KeyPrefix       = "osm:"
	KeyEventsPrefix = KeyPrefix + "events:" // osm:events:{topic}
)

// RedisEventBroker handles event publishing via Redis pub/sub
type RedisEventBroker struct {
	client rueidis.Client
	cfg    *config.RedisConfig
}

var (
	sharedBroker *RedisEventBroker
	brokerOnce   sync.Once
	brokerErr    error
)

// GetSharedBroker returns a singleton Redis event broker.
// Returns nil if Redis is not configured.
func GetSharedBroker() (*RedisEventBroker, error) {
	cfg := config.Get()
	if cfg == nil || !cfg.IsRedisConfigured() {
		return nil, nil
	}

	brokerOnce.Do(func() {
		sharedBroker, brokerErr = NewRedisEventBroker(&cfg.Redis)
	})

	return sharedBroker, brokerErr
}

// ResetSharedBroker resets the shared broker (useful for testing)
func ResetSharedBroker() {
	if sharedBroker != nil {
		sharedBroker.Close()
	}
	sharedBroker = nil
	brokerOnce = sync.Once{}
	brokerErr = nil
}

// NewRedisEventBroker creates a new Redis event broker
func NewRedisEventBroker(cfg *config.RedisConfig) (*RedisEventBroker, error) {
	if cfg.Host == "" {
		return nil, fmt.Errorf("redis host not configured")
	}

	port := cfg.Port
	if port == 0 {
		port = 6379
	}

	opts := rueidis.ClientOption{
		InitAddress:  []string{fmt.Sprintf("%s:%d", cfg.Host, port)},
		Username:     cfg.Username,
		Password:     cfg.Password,
		SelectDB:     cfg.DB,
		DisableCache: true,
	}

	client, err := rueidis.NewClient(opts)
	if err != nil {
		return nil, fmt.Errorf("failed to create redis client: %w", err)
	}

	return &RedisEventBroker{
		client: client,
		cfg:    cfg,
	}, nil
}

// Close closes the Redis client
func (b *RedisEventBroker) Close() {
	if b.client != nil {
		b.client.Close()
	}
}

// PublishEvent publishes an event to a topic channel
func (b *RedisEventBroker) PublishEvent(ctx context.Context, event *core.Event) error {
	data, err := json.Marshal(event)
	if err != nil {
		return fmt.Errorf("failed to marshal event: %w", err)
	}

	channel := KeyEventsPrefix + event.Topic
	cmd := b.client.B().Publish().Channel(channel).Message(string(data)).Build()
	return b.client.Do(ctx, cmd).Error()
}

// SubscribeEvents subscribes to event channels with pattern and calls handler for each event.
// This method blocks until the context is cancelled or an error occurs.
func (b *RedisEventBroker) SubscribeEvents(ctx context.Context, handler func(*core.Event)) error {
	pattern := KeyEventsPrefix + "*"

	err := b.client.Receive(ctx, b.client.B().Psubscribe().Pattern(pattern).Build(),
		func(msg rueidis.PubSubMessage) {
			if msg.Message != "" {
				var event core.Event
				if err := json.Unmarshal([]byte(msg.Message), &event); err == nil {
					handler(&event)
				}
			}
		})

	if err != nil && ctx.Err() != nil {
		return ctx.Err()
	}
	return err
}

// PublishEventData is a convenience function that creates an event and publishes it.
func (b *RedisEventBroker) PublishEventData(ctx context.Context, workspace, topic, source, dataType, runID, workflowName string, data interface{}) error {
	// Convert data to JSON string
	var dataJSON string
	switch v := data.(type) {
	case string:
		dataJSON = v
	default:
		jsonBytes, err := json.Marshal(data)
		if err != nil {
			dataJSON = fmt.Sprintf("%v", data)
		} else {
			dataJSON = string(jsonBytes)
		}
	}

	event := &core.Event{
		Topic:        topic,
		ID:           uuid.New().String(),
		Source:       source,
		DataType:     dataType,
		Workspace:    workspace,
		RunUUID:      runID,
		WorkflowName: workflowName,
		Data:         dataJSON,
		Timestamp:    time.Now(),
	}

	return b.PublishEvent(ctx, event)
}

// TryPublishEvent attempts to publish an event via Redis.
// Returns true if the event was published successfully, false otherwise.
// This is a convenience function that doesn't require pre-checking Redis configuration.
func TryPublishEvent(workspace, topic, source, dataType, runID, workflowName string, data interface{}) (bool, error) {
	broker, err := GetSharedBroker()
	if err != nil {
		return false, err
	}
	if broker == nil {
		return false, nil // Redis not configured
	}

	ctx := context.Background()
	if err := broker.PublishEventData(ctx, workspace, topic, source, dataType, runID, workflowName, data); err != nil {
		return false, err
	}
	return true, nil
}

package repository

import (
	"context"
	"time"

	"github.com/j3ssie/osmedeus/v5/internal/database"
	"github.com/uptrace/bun"
)

// EventLogRepository handles event log database operations
type EventLogRepository struct {
	db *bun.DB
}

// NewEventLogRepository creates a new event log repository
func NewEventLogRepository(db *bun.DB) *EventLogRepository {
	return &EventLogRepository{db: db}
}

// EventLogQuery represents query parameters for event search
type EventLogQuery struct {
	Topic        string
	Name         string
	Source       string
	Workspace    string
	ScanID       string
	WorkflowName string
	Processed    *bool
	StartTime    *time.Time
	EndTime      *time.Time
	Page         int
	PerPage      int
}

// Create creates a new event log
func (r *EventLogRepository) Create(ctx context.Context, event *database.EventLog) error {
	if event.CreatedAt.IsZero() {
		event.CreatedAt = time.Now()
	}
	_, err := r.db.NewInsert().Model(event).Exec(ctx)
	return err
}

// GetByID retrieves an event log by ID
func (r *EventLogRepository) GetByID(ctx context.Context, id int64) (*database.EventLog, error) {
	event := new(database.EventLog)
	err := r.db.NewSelect().
		Model(event).
		Where("id = ?", id).
		Scan(ctx)
	if err != nil {
		return nil, err
	}
	return event, nil
}

// GetByEventID retrieves an event log by event ID (UUID)
func (r *EventLogRepository) GetByEventID(ctx context.Context, eventID string) (*database.EventLog, error) {
	event := new(database.EventLog)
	err := r.db.NewSelect().
		Model(event).
		Where("event_id = ?", eventID).
		Scan(ctx)
	if err != nil {
		return nil, err
	}
	return event, nil
}

// Update updates an existing event log
func (r *EventLogRepository) Update(ctx context.Context, event *database.EventLog) error {
	_, err := r.db.NewUpdate().
		Model(event).
		WherePK().
		Exec(ctx)
	return err
}

// Delete deletes an event log by ID
func (r *EventLogRepository) Delete(ctx context.Context, id int64) error {
	_, err := r.db.NewDelete().
		Model((*database.EventLog)(nil)).
		Where("id = ?", id).
		Exec(ctx)
	return err
}

// ListByTopic lists events by topic with pagination
func (r *EventLogRepository) ListByTopic(ctx context.Context, topic string, page, perPage int) ([]*database.EventLog, int, error) {
	if page < 1 {
		page = 1
	}
	if perPage < 1 {
		perPage = 50
	}
	offset := (page - 1) * perPage

	var events []*database.EventLog
	count, err := r.db.NewSelect().
		Model(&events).
		Where("topic = ?", topic).
		Order("created_at DESC").
		Limit(perPage).
		Offset(offset).
		ScanAndCount(ctx)

	return events, count, err
}

// ListByScanID lists events for a specific scan (uses run_id column)
func (r *EventLogRepository) ListByScanID(ctx context.Context, scanID string) ([]*database.EventLog, error) {
	var events []*database.EventLog
	err := r.db.NewSelect().
		Model(&events).
		Where("run_id = ?", scanID).
		Order("created_at ASC").
		Scan(ctx)
	return events, err
}

// ListByWorkspace lists events for a workspace with pagination
func (r *EventLogRepository) ListByWorkspace(ctx context.Context, workspace string, page, perPage int) ([]*database.EventLog, int, error) {
	if page < 1 {
		page = 1
	}
	if perPage < 1 {
		perPage = 50
	}
	offset := (page - 1) * perPage

	var events []*database.EventLog
	count, err := r.db.NewSelect().
		Model(&events).
		Where("workspace = ?", workspace).
		Order("created_at DESC").
		Limit(perPage).
		Offset(offset).
		ScanAndCount(ctx)

	return events, count, err
}

// ListUnprocessed lists unprocessed events
func (r *EventLogRepository) ListUnprocessed(ctx context.Context, limit int) ([]*database.EventLog, error) {
	if limit < 1 {
		limit = 100
	}

	var events []*database.EventLog
	err := r.db.NewSelect().
		Model(&events).
		Where("processed = ?", false).
		Order("created_at ASC").
		Limit(limit).
		Scan(ctx)
	return events, err
}

// MarkProcessed marks an event as processed
func (r *EventLogRepository) MarkProcessed(ctx context.Context, id int64, errorMsg string) error {
	now := time.Now()
	_, err := r.db.NewUpdate().
		Model((*database.EventLog)(nil)).
		Set("processed = ?", true).
		Set("processed_at = ?", now).
		Set("error = ?", errorMsg).
		Where("id = ?", id).
		Exec(ctx)
	return err
}

// Search searches events with multiple criteria
func (r *EventLogRepository) Search(ctx context.Context, query EventLogQuery) ([]*database.EventLog, int, error) {
	if query.Page < 1 {
		query.Page = 1
	}
	if query.PerPage < 1 {
		query.PerPage = 50
	}
	offset := (query.Page - 1) * query.PerPage

	var events []*database.EventLog
	q := r.db.NewSelect().Model(&events)

	if query.Topic != "" {
		q = q.Where("topic = ?", query.Topic)
	}
	if query.Name != "" {
		q = q.Where("name = ?", query.Name)
	}
	if query.Source != "" {
		q = q.Where("source = ?", query.Source)
	}
	if query.Workspace != "" {
		q = q.Where("workspace = ?", query.Workspace)
	}
	if query.ScanID != "" {
		q = q.Where("run_id = ?", query.ScanID)
	}
	if query.WorkflowName != "" {
		q = q.Where("workflow_name = ?", query.WorkflowName)
	}
	if query.Processed != nil {
		q = q.Where("processed = ?", *query.Processed)
	}
	if query.StartTime != nil {
		q = q.Where("created_at >= ?", *query.StartTime)
	}
	if query.EndTime != nil {
		q = q.Where("created_at <= ?", *query.EndTime)
	}

	count, err := q.
		Order("created_at DESC").
		Limit(query.PerPage).
		Offset(offset).
		ScanAndCount(ctx)

	return events, count, err
}

// CountByTopic returns the count of events for a topic
func (r *EventLogRepository) CountByTopic(ctx context.Context, topic string) (int, error) {
	return r.db.NewSelect().
		Model((*database.EventLog)(nil)).
		Where("topic = ?", topic).
		Count(ctx)
}

// GetTopicSummary returns a summary of events by topic
func (r *EventLogRepository) GetTopicSummary(ctx context.Context) (map[string]int, error) {
	var results []struct {
		Topic string `bun:"topic"`
		Count int    `bun:"count"`
	}

	err := r.db.NewSelect().
		Model((*database.EventLog)(nil)).
		ColumnExpr("topic, COUNT(*) AS count").
		Group("topic").
		Order("count DESC").
		Scan(ctx, &results)

	if err != nil {
		return nil, err
	}

	summary := make(map[string]int)
	for _, r := range results {
		summary[r.Topic] = r.Count
	}

	return summary, nil
}

// DeleteOlderThan deletes events older than the specified time
func (r *EventLogRepository) DeleteOlderThan(ctx context.Context, before time.Time) (int64, error) {
	res, err := r.db.NewDelete().
		Model((*database.EventLog)(nil)).
		Where("created_at < ?", before).
		Exec(ctx)
	if err != nil {
		return 0, err
	}
	return res.RowsAffected()
}

// DeleteByWorkspace deletes all events for a workspace
func (r *EventLogRepository) DeleteByWorkspace(ctx context.Context, workspace string) (int64, error) {
	res, err := r.db.NewDelete().
		Model((*database.EventLog)(nil)).
		Where("workspace = ?", workspace).
		Exec(ctx)
	if err != nil {
		return 0, err
	}
	return res.RowsAffected()
}

// CreateBatch creates multiple event logs in a batch
func (r *EventLogRepository) CreateBatch(ctx context.Context, events []*database.EventLog) error {
	if len(events) == 0 {
		return nil
	}

	now := time.Now()
	for _, event := range events {
		if event.CreatedAt.IsZero() {
			event.CreatedAt = now
		}
	}

	_, err := r.db.NewInsert().Model(&events).Exec(ctx)
	return err
}

// GetRecentByWorkflow gets recent events for a workflow
func (r *EventLogRepository) GetRecentByWorkflow(ctx context.Context, workflowName string, limit int) ([]*database.EventLog, error) {
	if limit < 1 {
		limit = 10
	}

	var events []*database.EventLog
	err := r.db.NewSelect().
		Model(&events).
		Where("workflow_name = ?", workflowName).
		Order("created_at DESC").
		Limit(limit).
		Scan(ctx)
	return events, err
}

package internal

import (
	"github.com/antlr4-go/antlr/v4"

	"github.com/MontFerret/ferret/v2/pkg/bytecode"
	"github.com/MontFerret/ferret/v2/pkg/compiler/internal/core"
	parserd "github.com/MontFerret/ferret/v2/pkg/parser/diagnostics"
	"github.com/MontFerret/ferret/v2/pkg/parser/fql"
	"github.com/MontFerret/ferret/v2/pkg/source"
)

type waitEventCompileState struct {
	span       source.Span
	srcReg     bytecode.Operand
	eventReg   bytecode.Operand
	optsReg    bytecode.Operand
	timeoutReg bytecode.Operand
}

func (c *WaitCompiler) compileEvent(ctx fql.IWaitForEventExpressionContext) bytecode.Operand {
	if waitForEventTriggerClause(ctx) != nil {
		return c.compileEventWithTriggerCleanup(ctx)
	}

	state, ok := c.buildWaitEventState(ctx)
	if !ok {
		return bytecode.NoopOperand
	}

	streamReg := c.ctx.Function.Registers.Allocate()
	resultReg := c.ctx.Function.Registers.Allocate()

	c.ctx.Program.Emitter.EmitLoadNone(resultReg)
	c.emitWaitEventStreamSetup(state, streamReg)
	c.compileWaitEventTrigger(ctx)

	start := c.ctx.Program.Emitter.NewLabel()
	end := c.ctx.Program.Emitter.NewLabel()

	c.ctx.Program.Emitter.MarkLabel(start)
	c.emitWaitEventIteration(ctx, state, streamReg, resultReg, bytecode.NoopOperand, start, end)

	c.ctx.Program.Emitter.MarkLabel(end)
	c.emitWaitEventCleanup(state, streamReg)

	return resultReg
}

func (c *WaitCompiler) compileEventWithTimeoutRecovery(
	ctx fql.IWaitForEventExpressionContext,
	timeoutLabel, endLabel core.Label,
) bytecode.Operand {
	if waitForEventTriggerClause(ctx) != nil {
		return c.compileEventWithTriggerTimeoutCleanup(ctx, timeoutLabel, endLabel)
	}

	streamReg := c.ctx.Function.Registers.Allocate()
	resultReg := c.ctx.Function.Registers.Allocate()
	timeoutStateReg := c.ctx.Function.Registers.Allocate()

	c.ctx.Program.Emitter.EmitLoadNone(resultReg)
	c.ctx.Program.Emitter.EmitBoolean(timeoutStateReg, false)

	state, ok := c.buildWaitEventState(ctx)
	if !ok {
		return bytecode.NoopOperand
	}

	c.emitWaitEventStreamSetup(state, streamReg)
	c.compileWaitEventTrigger(ctx)

	start := c.ctx.Program.Emitter.NewLabel()
	iterationDone := c.ctx.Program.Emitter.NewLabel()
	cleanup := c.ctx.Program.Emitter.NewLabel()

	c.ctx.Program.Emitter.MarkLabel(start)
	c.emitWaitEventIteration(ctx, state, streamReg, resultReg, timeoutStateReg, start, iterationDone)

	c.ctx.Program.Emitter.EmitJump(cleanup)
	c.ctx.Program.Emitter.MarkLabel(iterationDone)
	c.ctx.Program.Emitter.EmitJump(cleanup)

	c.ctx.Program.Emitter.MarkLabel(cleanup)
	c.emitWaitEventCleanup(state, streamReg)

	c.ctx.Program.Emitter.EmitJumpIfTrue(timeoutStateReg, timeoutLabel)
	c.ctx.Program.Emitter.EmitJump(endLabel)

	return resultReg
}

func (c *WaitCompiler) compileEventWithTriggerCleanup(ctx fql.IWaitForEventExpressionContext) bytecode.Operand {
	streamReg := c.ctx.Function.Registers.Allocate()
	resultReg := c.ctx.Function.Registers.Allocate()
	streamReadyReg := c.ctx.Function.Registers.Allocate()

	c.ctx.Program.Emitter.EmitLoadNone(resultReg)
	c.ctx.Program.Emitter.EmitBoolean(streamReadyReg, false)

	startCatch := c.ctx.Program.Emitter.Size()
	state, ok := c.buildWaitEventState(ctx)
	if !ok {
		return bytecode.NoopOperand
	}

	c.emitWaitEventStreamSetupWithReady(state, streamReg, streamReadyReg)
	c.compileWaitEventTrigger(ctx)

	start := c.ctx.Program.Emitter.NewLabel()
	iterationDone := c.ctx.Program.Emitter.NewLabel()
	exit := c.ctx.Program.Emitter.NewLabel("waitfor", "event", "trigger", "exit")

	c.ctx.Program.Emitter.MarkLabel(start)
	c.emitWaitEventIteration(ctx, state, streamReg, resultReg, bytecode.NoopOperand, start, iterationDone)

	c.ctx.Program.Emitter.MarkLabel(iterationDone)
	c.emitWaitEventCleanupIfReady(state, streamReg, streamReadyReg)
	c.ctx.Program.Emitter.EmitJump(exit)

	endCatchExclusive := c.ctx.Program.Emitter.Size()
	errorHandlerPC := c.ctx.Program.Emitter.Size()
	c.emitWaitEventCleanupIfReady(state, streamReg, streamReadyReg)
	c.ctx.Program.Emitter.Emit(bytecode.OpRethrow)

	c.ctx.Program.Emitter.MarkLabel(exit)
	c.ctx.Program.Emitter.EmitAB(bytecode.OpMove, resultReg, resultReg)

	c.ctx.Program.CatchTable.Push(startCatch, endCatchExclusive-1, errorHandlerPC)

	return resultReg
}

func (c *WaitCompiler) compileEventWithTriggerTimeoutCleanup(
	ctx fql.IWaitForEventExpressionContext,
	timeoutLabel, endLabel core.Label,
) bytecode.Operand {
	streamReg := c.ctx.Function.Registers.Allocate()
	resultReg := c.ctx.Function.Registers.Allocate()
	timeoutStateReg := c.ctx.Function.Registers.Allocate()
	streamReadyReg := c.ctx.Function.Registers.Allocate()

	c.ctx.Program.Emitter.EmitLoadNone(resultReg)
	c.ctx.Program.Emitter.EmitBoolean(timeoutStateReg, false)
	c.ctx.Program.Emitter.EmitBoolean(streamReadyReg, false)

	startCatch := c.ctx.Program.Emitter.Size()
	state, ok := c.buildWaitEventState(ctx)
	if !ok {
		return bytecode.NoopOperand
	}

	c.emitWaitEventStreamSetupWithReady(state, streamReg, streamReadyReg)
	c.compileWaitEventTrigger(ctx)

	start := c.ctx.Program.Emitter.NewLabel()
	iterationDone := c.ctx.Program.Emitter.NewLabel()
	cleanup := c.ctx.Program.Emitter.NewLabel()

	c.ctx.Program.Emitter.MarkLabel(start)
	c.emitWaitEventIteration(ctx, state, streamReg, resultReg, timeoutStateReg, start, iterationDone)

	c.ctx.Program.Emitter.EmitJump(cleanup)
	c.ctx.Program.Emitter.MarkLabel(iterationDone)
	c.ctx.Program.Emitter.EmitJump(cleanup)

	c.ctx.Program.Emitter.MarkLabel(cleanup)
	c.emitWaitEventCleanupIfReady(state, streamReg, streamReadyReg)

	c.ctx.Program.Emitter.EmitJumpIfTrue(timeoutStateReg, timeoutLabel)
	c.ctx.Program.Emitter.EmitJump(endLabel)

	endCatchExclusive := c.ctx.Program.Emitter.Size()
	errorHandlerPC := c.ctx.Program.Emitter.Size()
	c.emitWaitEventCleanupIfReady(state, streamReg, streamReadyReg)
	c.ctx.Program.Emitter.Emit(bytecode.OpRethrow)

	c.ctx.Program.CatchTable.Push(startCatch, endCatchExclusive-1, errorHandlerPC)

	return resultReg
}

func (c *WaitCompiler) buildWaitEventState(ctx fql.IWaitForEventExpressionContext) (waitEventCompileState, bool) {
	state := waitEventCompileState{
		span:     waitForSpan(ctx.WaitForEventSource(), ctx),
		srcReg:   c.CompileWaitForEventSource(ctx.WaitForEventSource()),
		eventReg: c.CompileWaitForEventName(ctx.WaitForEventName()),
	}

	if opts := ctx.OptionsClause(); opts != nil {
		state.optsReg = c.CompileOptionsClause(opts)
	}

	if timeout := waitForEventTimeoutClause(ctx); timeout != nil {
		state.timeoutReg = c.recovery.CompileDurationExpression(timeout.Expression())
		if state.timeoutReg == bytecode.NoopOperand {
			return waitEventCompileState{}, false
		}
	}

	return state, true
}

func (c *WaitCompiler) emitWaitEventStreamSetup(state waitEventCompileState, streamReg bytecode.Operand) {
	c.emitWaitEventStreamSetupWithReady(state, streamReg, bytecode.NoopOperand)
}

func (c *WaitCompiler) emitWaitEventStreamSetupWithReady(state waitEventCompileState, streamReg, streamReadyReg bytecode.Operand) {
	c.ctx.Program.Emitter.WithSpan(state.span, func() {
		c.ctx.Program.Emitter.EmitMove(streamReg, state.srcReg)
		c.ctx.Program.Emitter.EmitABC(bytecode.OpStream, streamReg, state.eventReg, state.optsReg)
		if streamReadyReg != bytecode.NoopOperand {
			c.ctx.Program.Emitter.EmitBoolean(streamReadyReg, true)
		}
		c.ctx.Program.Emitter.EmitABC(bytecode.OpStreamIter, streamReg, streamReg, state.timeoutReg)
	})
}

func (c *WaitCompiler) compileWaitEventTrigger(ctx fql.IWaitForEventExpressionContext) {
	if ctx == nil {
		return
	}

	trigger := waitForEventTriggerClause(ctx)
	if trigger == nil {
		return
	}

	c.compileWaitForTriggerClause(trigger)
}

func (c *WaitCompiler) compileWaitForTriggerClause(ctx fql.IWaitForTriggerClauseContext) {
	if ctx == nil {
		return
	}

	c.ctx.Function.Symbols.EnterScope()
	defer c.ctx.Function.Symbols.ExitScope()

	if c.ctx.Program.Semantics != nil {
		c.ctx.Program.Semantics.EnterScope(parserd.SpanFromRuleContext(ctx.(antlr.ParserRuleContext)))
		defer c.ctx.Program.Semantics.ExitScope()
	}

	if inline := ctx.WaitForTriggerInlineStatement(); inline != nil {
		c.compileWaitForTriggerInlineStatement(inline)
		return
	}

	for _, stmt := range ctx.AllWaitForTriggerStatement() {
		c.compileWaitForTriggerStatement(stmt)
	}
}

func (c *WaitCompiler) compileWaitForTriggerStatement(ctx fql.IWaitForTriggerStatementContext) {
	if ctx == nil {
		return
	}

	if vd := ctx.VariableDeclaration(); vd != nil {
		c.bindings.CompileVariableDeclaration(vd)
	} else if as := ctx.AssignmentStatement(); as != nil {
		c.bindings.CompileAssignmentStatement(as)
	} else if ds := ctx.DeleteStatement(); ds != nil {
		c.bindings.CompileDeleteStatement(ds)
	} else if fce := ctx.FunctionCallExpression(); fce != nil {
		c.exprs.CompileFunctionCallExpression(fce)
	} else if wfe := ctx.WaitForExpression(); wfe != nil {
		c.Compile(wfe)
	} else if de := ctx.DispatchExpression(); de != nil {
		c.dispatch.Compile(de)
	}
}

func (c *WaitCompiler) compileWaitForTriggerInlineStatement(ctx fql.IWaitForTriggerInlineStatementContext) {
	if ctx == nil {
		return
	}

	if vd := ctx.VariableDeclaration(); vd != nil {
		c.bindings.CompileVariableDeclaration(vd)
	} else if as := ctx.AssignmentStatement(); as != nil {
		c.bindings.CompileAssignmentStatement(as)
	} else if ds := ctx.DeleteStatement(); ds != nil {
		c.bindings.CompileDeleteStatement(ds)
	} else if fce := ctx.FunctionCallNoRecoveryExpression(); fce != nil {
		c.exprs.CompileFunctionCallNoRecoveryExpression(fce)
	} else if dispatch := ctx.WaitForTriggerInlineDispatchStatement(); dispatch != nil {
		c.compileWaitForTriggerInlineDispatchStatement(dispatch)
	}
}

func (c *WaitCompiler) compileWaitForTriggerInlineDispatchStatement(ctx fql.IWaitForTriggerInlineDispatchStatementContext) {
	if ctx == nil {
		return
	}

	c.dispatch.compileCore(
		ctx.DispatchTarget(),
		ctx.DispatchEventName(),
		ctx.DispatchWithClause(),
		ctx.DispatchOptionsClause(),
		c.dispatch.dispatchSpan(ctx),
	)
}

func (c *WaitCompiler) emitWaitEventIteration(
	ctx fql.IWaitForEventExpressionContext,
	state waitEventCompileState,
	streamReg, resultReg, timeoutStateReg bytecode.Operand,
	restartLabel, doneLabel core.Label,
) {
	c.ctx.Program.Emitter.WithSpan(state.span, func() {
		if timeoutStateReg != bytecode.NoopOperand {
			c.ctx.Program.Emitter.EmitIterNextTimeout(streamReg, timeoutStateReg, doneLabel)
			return
		}

		c.ctx.Program.Emitter.EmitIterNext(streamReg, doneLabel)
	})

	filters := ctx.AllEventFilterClause()
	if len(filters) == 0 {
		c.ctx.Program.Emitter.WithSpan(state.span, func() {
			c.ctx.Program.Emitter.EmitIterValue(resultReg, streamReg)
		})
		return
	}

	eventValReg, _ := c.ctx.Function.Symbols.DeclareLocal(core.PseudoVariable, core.TypeUnknown)

	c.ctx.Program.Emitter.WithSpan(state.span, func() {
		c.ctx.Program.Emitter.EmitIterValue(eventValReg, streamReg)
	})

	for _, filter := range filters {
		cond := c.exprs.CompileWithImplicitCurrent(filter.Expression())
		c.ctx.Program.Emitter.EmitJumpIfFalse(cond, restartLabel)
	}

	c.ctx.Program.Emitter.WithSpan(state.span, func() {
		c.ctx.Program.Emitter.EmitMove(resultReg, eventValReg)
	})
}

func (c *WaitCompiler) emitWaitEventCleanup(state waitEventCompileState, streamReg bytecode.Operand) {
	c.ctx.Program.Emitter.WithSpan(state.span, func() {
		c.ctx.Program.Emitter.EmitA(bytecode.OpClose, streamReg)
	})
}

func (c *WaitCompiler) emitWaitEventCleanupIfReady(state waitEventCompileState, streamReg, streamReadyReg bytecode.Operand) {
	if streamReadyReg == bytecode.NoopOperand {
		c.emitWaitEventCleanup(state, streamReg)

		return
	}

	skip := c.ctx.Program.Emitter.NewLabel("waitfor", "event", "cleanup", "skip")
	c.ctx.Program.Emitter.EmitJumpIfFalse(streamReadyReg, skip)
	c.emitWaitEventCleanup(state, streamReg)
	c.ctx.Program.Emitter.EmitBoolean(streamReadyReg, false)
	c.ctx.Program.Emitter.MarkLabel(skip)
}

// CompileWaitForEventName processes the event name expression in a WAITFOR statement.
func (c *WaitCompiler) CompileWaitForEventName(ctx fql.IWaitForEventNameContext) bytecode.Operand {
	if ctx == nil {
		return bytecode.NoopOperand
	}

	return c.exprs.Compile(ctx.Expression())
}

// CompileWaitForEventSource processes the event source expression in a WAITFOR statement.
func (c *WaitCompiler) CompileWaitForEventSource(ctx fql.IWaitForEventSourceContext) bytecode.Operand {
	if ctx == nil {
		return bytecode.NoopOperand
	}

	return c.exprs.Compile(ctx.Expression())
}

// CompileOptionsClause processes the options clause in a WAITFOR statement.
func (c *WaitCompiler) CompileOptionsClause(ctx fql.IOptionsClauseContext) bytecode.Operand {
	if ol := ctx.ObjectLiteral(); ol != nil {
		return c.literals.CompileObjectLiteral(ol)
	}

	return bytecode.NoopOperand
}

